3	import java.util.List;
4	import java.util.Map;
5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // projects references clients; drop referential integrity so both tables can be truncated
36	        // (and their identity counters restarted) regardless of FK order.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        jdbc.execute("TRUNCATE TABLE project_tags RESTART IDENTITY");
39	        jdbc.execute("TRUNCATE TABLE tags RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE line_items RESTART IDENTITY");
42	        jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
43	        jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
44	        jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
45	        jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
46	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
47	    }
48	
49	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
50	    @PostMapping("/seed")
51	    @SuppressWarnings("unchecked")
52	    public void seed(@RequestBody Map<String, Object> fixture) {
53	        List<Map<String, Object>> clients =
54	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
55	        for (Map<String, Object> c : clients) {
56	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
57	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"));
58	        }
59	        List<Map<String, Object>> projects =
60	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
61	        for (Map<String, Object> p : projects) {
62	            jdbc.update("INSERT INTO projects (id, name, client_id) VALUES (?, ?, ?)",
63	                    ((Number) p.get("id")).longValue(), p.get("name"),
64	                    ((Number) p.get("clientId")).longValue());
65	        }
66	        List<Map<String, Object>> contacts =
67	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
68	        for (Map<String, Object> ct : contacts) {
69	            jdbc.update(
70	                    "INSERT INTO contacts (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
71	                    ((Number) ct.get("id")).longValue(),
72	                    ((Number) ct.get("clientId")).longValue(), ct.get("name"), ct.get("email"),
73	                    ct.get("role"));
74	        }
75	        List<Map<String, Object>> invoices =
76	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
77	        for (Map<String, Object> in : invoices) {
78	            Object status = in.get("status");
79	            Object amount = in.get("amount");
80	            Object issuedDate = in.get("issuedDate");
81	            Object dueDate = in.get("dueDate");
82	            // Insert only the columns the fixture supplies, so the table's own defaults apply when a
83	            // fixture omits them (a plain null would trip the NOT NULL columns). status defaults to
84	            // DRAFT and amount defaults to 0 — an invoice's amount is now derived from its line
85	            // items, so fixtures list lineItems rather than a single typed amount.
86	            StringBuilder cols = new StringBuilder("id, project_id, status");
87	            StringBuilder marks = new StringBuilder("?, ?, ?");
88	            List<Object> args = new java.util.ArrayList<>(List.of(
89	                    ((Number) in.get("id")).longValue(),
90	                    ((Number) in.get("projectId")).longValue(),
91	                    status == null ? "DRAFT" : status.toString()));
92	            if (amount != null) {
93	                cols.append(", amount");
94	                marks.append(", ?");
95	                args.add(((Number) amount).doubleValue());
96	            }
97	            if (issuedDate != null) {
98	                cols.append(", issued_date");
99	                marks.append(", ?");
100	                args.add(issuedDate.toString());
101	            }
102	            if (dueDate != null) {
103	                cols.append(", due_date");
104	                marks.append(", ?");
105	                args.add(dueDate.toString());
106	            }
107	            jdbc.update("INSERT INTO invoices (" + cols + ") VALUES (" + marks + ")",
108	                    args.toArray());
109	            List<Map<String, Object>> lineItems =
110	                    (List<Map<String, Object>>) in.getOrDefault("lineItems", List.of());
111	            for (Map<String, Object> li : lineItems) {
112	                jdbc.update(
113	                        "INSERT INTO line_items (id, invoice_id, description, qty, unit_price)"
114	                                + " VALUES (?, ?, ?, ?, ?)",
115	                        ((Number) li.get("id")).longValue(),
116	                        ((Number) in.get("id")).longValue(), li.get("description"),
117	                        ((Number) li.get("qty")).intValue(),
118	                        ((Number) li.get("unitPrice")).doubleValue());
119	            }
